question.answer:
package main

import "fmt"

func describe(item any) string {
	switch v := item.(type) {
	case nil:
		return "empty hands"
	case int:
		return fmt.Sprintf("%d coins", v)
	case string:
		return "a note reading " + v
	default:
		return "unclaimed"
	}
}

func coins(item any) (int, bool) {
	n, ok := item.(int)
	return n, ok
}

