question.answer:
package main

type Parcel interface {
	weight() int
	sealed()
}

type Letter struct {
	Grams int
}

func (l Letter) weight() int { return l.Grams }

func (l Letter) sealed() {}

type Box struct {
	Grams int
}

func (b Box) weight() int { return b.Grams }

func (b Box) sealed() {}

type Crate struct {
	Grams int
}

func (c Crate) weight() int { return c.Grams }

func (c Crate) sealed() {}

type Sack struct {
	Grams int
}

func (s Sack) weight() int { return s.Grams }

func carried(item any) bool {
	_, ok := item.(Parcel)
	return ok
}

func load(items []Parcel) int {
	total := 0
	for _, item := range items {
		total += item.weight()
	}
	return total
}

