question.answer:
package main

import (
	"errors"
	"fmt"
)

var ErrUnpriced = errors.New("no fare for this ticket")

type Ticket interface {
	holder() string
}

type Single struct {
	Name string
}

func (s Single) holder() string { return s.Name }

type Return struct {
	Name string
}

func (r Return) holder() string { return r.Name }

type DayPass struct {
	Name string
}

func (d DayPass) holder() string { return d.Name }

func fare(t Ticket) (int, error) {
	switch t.(type) {
	case Single, *Single:
		return 350, nil
	case Return, *Return:
		return 620, nil
	default:
		return 0, fmt.Errorf("%s: %w", t.holder(), ErrUnpriced)
	}
}

func unpriced(err error) bool {
	return errors.Is(err, ErrUnpriced)
}
